            new() { Id = 7, Title = "Quantum Mechanics", Code = "PHYS 401", Description = "Wave functions, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Lisa Nakamura", InstructorBio = "Dr. Nakamura's research focuses on quantum computing and quantum information theory.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
